theorem norm_logRem_sub_le [CharZero k] (hp : p.Prime) (hpk : ‖(p : k)‖ < 1) {a b : k}
    (ha : ‖a‖ ≤ ‖2 * (p : k)‖) (hb : ‖b‖ ≤ ‖2 * (p : k)‖) :
    ‖logRem a - logRem b‖ ≤ ‖(p : k)‖ * ‖a - b‖

theorem norm_logTerm_sub_le [CharZero k] (hp : p.Prime) (hpk : ‖(p : k)‖ < 1) {a b : k}
    (ha : ‖a‖ ≤ ‖2 * (p : k)‖) (hb : ‖b‖ ≤ ‖2 * (p : k)‖) (n : ℕ) :
    ‖logTerm (1 + a) (n + 1) - logTerm (1 + b) (n + 1)‖ ≤ ‖(p : k)‖ * ‖a - b‖

theorem tendsto_pow_sub_one_div [CharZero k] (hp : p.Prime) (hpk : ‖(p : k)‖ < 1) {x : k}
    (hx : ‖x - 1‖ < 1) :
    Tendsto (fun m : ℕ => (x ^ (p ^ m) - 1) / ((p : k) ^ m)) atTop (𝓝 (padicLog x))

lemma some_ext {W : WeierstrassCurve k} {x y x' y' : k} {h : W.toAffine.Nonsingular x y}
    {h' : W.toAffine.Nonsingular x' y'} (hx : x = x') (hy : y = y') :
    Affine.Point.some x y h = Affine.Point.some x' y' h'

theorem X_ne_of_smul {m : ℕ} (hm : 1 ≤ m) {X Y : F} {hQ : W.Nonsingular X Y}
    (hmP : m • Point.some x y h = Point.some X Y hQ)
    (h₁ : (m - 1) • Point.some x y h ≠ 0) (h₂ : (m + 1) • Point.some x y h ≠ 0) : X ≠ x

theorem two_nsmul_some_eq_zero_iff [NeZero (2 : K)] {x y : K}
    (h : (legendre l).toAffine.Nonsingular x y) :
    2 • Affine.Point.some x y h = 0 ↔ y = 0
